import json
import re
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
BACKEND = ROOT / 'backend'
if str(BACKEND) not in sys.path:
    sys.path.insert(0, str(BACKEND))

from core.connections.pos_runtime_resolver import list_pos_runtime_contexts
from core.sql_first.connection_factory import get_edarsahub_pymssql_connection, get_external_sql_connection

TOKENS = ('client','cliente','customer','rfc','razon','nombre','email','correo','telefono','tel','cel','direccion','domicilio','calle','colonia','municipio','ciudad','estado','pais','postal','cp','tipo','grupo','segment','sector','ruta','cadena','giro','credito','moneda','activo','estatus','fecha','alta','modif','subrog','clasif')

CANON = {
 'rfc':'Cliente_Catalogo.RFC','razon':'Cliente_Catalogo.RazonSocial','nombre':'Cliente_Catalogo.NombreComercial',
 'email':'Cliente_Catalogo.EmailPrincipal|Cliente_Contactos.Email','correo':'Cliente_Catalogo.EmailPrincipal|Cliente_Contactos.Email',
 'telefono':'Cliente_Catalogo.TelefonoPrincipal|Cliente_Contactos.Telefono','tel':'Cliente_Catalogo.TelefonoPrincipal|Cliente_Contactos.Telefono','cel':'Cliente_Contactos.Celular',
 'direccion':'Cliente_Direcciones','domicilio':'Cliente_Direcciones','calle':'Cliente_Direcciones','colonia':'Cliente_Direcciones','municipio':'Cliente_Direcciones','ciudad':'Cliente_Direcciones','estado':'Cliente_Direcciones','pais':'Cliente_Direcciones','postal':'Cliente_Direcciones','cp':'Cliente_Direcciones',
 'tipo':'Cliente_Grupos/catalogo_equivalente','grupo':'Cliente_Grupos/catalogo_equivalente','segment':'relacion_comercial_existente','sector':'Cliente_Catalogo.SectorID_si_equivalente','ruta':'relacion_ruta_existente','cadena':'relacion_jerarquica_existente','giro':'catalogo_comercial_existente',
 'credito':'Cliente_Catalogo.LimiteCredito|DiasCredito','moneda':'Cliente_Catalogo.MonedaID','activo':'Cliente_Catalogo.Activo','estatus':'Cliente_Catalogo.Activo/catalogo_equivalente','fecha':'fecha_auditoria_equivalente','alta':'Cliente_Catalogo.FechaAlta','modif':'auditoria_existente','subrog':'relacion_cliente_cliente_existente','clasif':'clasificacion_existente'
}

def norm(v): return re.sub(r'[^a-z0-9]+','',str(v or '').lower())

def dest(col):
    n=norm(col)
    if n in {'id','clienteid','idcliente','customerid','clientid'}: return 'identidad_origen->ClienteID'
    if n in {'clave','clavecliente','codigocliente','codigo'}: return 'CodigoCliente+identidad(sistema,unidad,clave)'
    for k,v in CANON.items():
        if k in n: return v
    return 'PENDIENTE_SEMANTICA_NO_CREAR_COLUMNA'

def cols(cur,schema,table):
    cur.execute("SELECT COLUMN_NAME,DATA_TYPE,IS_NULLABLE FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=%s AND TABLE_NAME=%s ORDER BY ORDINAL_POSITION",(schema,table))
    return cur.fetchall()

def tables(cur):
    cur.execute("""
      SELECT s.name schema_name,t.name table_name,SUM(CASE WHEN p.index_id IN (0,1) THEN p.rows ELSE 0 END) row_count
      FROM sys.tables t JOIN sys.schemas s ON s.schema_id=t.schema_id LEFT JOIN sys.partitions p ON p.object_id=t.object_id
      WHERE t.name LIKE '%client%' OR t.name LIKE '%cliente%' OR t.name LIKE '%customer%'
         OR EXISTS(SELECT 1 FROM sys.columns c WHERE c.object_id=t.object_id AND (c.name LIKE '%cliente%' OR c.name LIKE '%client%' OR c.name LIKE '%rfc%' OR c.name LIKE '%telefono%' OR c.name LIKE '%email%' OR c.name LIKE '%grupo%' OR c.name LIKE '%segment%' OR c.name LIKE '%sector%' OR c.name LIKE '%ruta%'))
      GROUP BY s.name,t.name ORDER BY row_count DESC,t.name
    """)
    return cur.fetchall()

def hub():
    conn=get_edarsahub_pymssql_connection(timeout=30,login_timeout=10)
    try:
      cur=conn.cursor(as_dict=True); out={}
      for t in ('Cliente_Catalogo','Cliente_Contactos','Cliente_Direcciones','Cliente_Grupos','CRM_Cuentas','CavaSocios_Socios'):
        out[t]=cols(cur,'dbo',t)
      return out
    finally: conn.close()

def source(ctx):
    conn=get_external_sql_connection(ctx.external_connection_config(as_dict=True))
    try:
      cur=conn.cursor(as_dict=True); ranked=[]
      for t in tables(cur):
        relevant=[]
        for c in cols(cur,t['schema_name'],t['table_name']):
          n=norm(c['COLUMN_NAME'])
          if any(norm(x) in n for x in TOKENS) or n in {'id','clave','codigo'}:
            relevant.append({'c':c['COLUMN_NAME'],'t':c['DATA_TYPE'],'n':c['IS_NULLABLE'],'d':dest(c['COLUMN_NAME'])})
        if relevant:
          score=len(relevant)+(20 if any(x in norm(t['table_name']) for x in ('cliente','client','customer')) else 0)
          ranked.append((score,int(t.get('row_count') or 0),t['schema_name'],t['table_name'],relevant))
      ranked.sort(reverse=True)
      return {'u':ctx.unidad_codigo,'s':ctx.system_type,'db':ctx.database,'tabs':[{'t':f'{a}.{b}','rows':r,'f':fs[:18]} for _,r,a,b,fs in ranked[:6]]}
    finally: conn.close()

def test_live_map_v2():
    ev={'hub':hub(),'sources':[],'errors':[]}
    contexts=list_pos_runtime_contexts(system_types=('SOFTRESTAURANT','MPRO'))
    ev['contexts']=[{'u':c.unidad_codigo,'s':c.system_type,'db':c.database} for c in contexts]
    for c in contexts:
      try: ev['sources'].append(source(c))
      except Exception as e: ev['errors'].append({'u':c.unidad_codigo,'s':c.system_type,'e':type(e).__name__+':'+str(e)[:160]})
    ev['rules']={'master':'dbo.Cliente_Catalogo','crm':'ClienteID canonico','cava':'ClienteID sin duplicar datos generales','identity':'sistema+unidad+clave; nombre nunca fusiona','schema':'reusar antes de crear'}
    raise AssertionError('CLIENTES_CANONICAL_MAP_V2_JSON='+json.dumps(ev,ensure_ascii=False,separators=(',',':'),default=str))
